  P.zh.PRIMP = { sub: '補土專用底漆（隨補土附屬）', pack: 'フラットパテ：20 ml（軟管附）；アドハー3500：100 ml × 2 罐／箱', colour: '—', kind: '專用底漆', use: '補填處的接著處理：以附屬小刷薄塗，乾燥後補填。', role: '補土的接著保證：釘頭・螺絲孔、裂縫、缺角先點塗底漆，乾燥後補填。', areas: ['補土的所有補填處'], adv: ['隨補土附屬', '小刷點塗、用量少'], feat: ['與フラットパテ／アドハー3500 配套'], data: [['乾燥時間', '未公布（TBC）'], ['包裝', '20 ml（軟管附）／100 ml × 2（卡匣每箱附）']], safety: [['乾燥', '未乾燥即補填會影響接著'], ['SDS', '製造商 SDS']] };
  T.zh = {
    planC: { tag: '規劃', title: 'RC 構造物：目地的種類與動量', short: '伸縮目地（寬 20、深 15 mm 本例）、打繼目地、收縮裂縫分別處理：伸縮目地要背襯材與二面接著；裂縫切 U 形溝後填充。確認是否暴露、是否塗裝。', overview: '橋梁・橋脚、壁高欄、擁壁、箱涵、U 字溝：目地暴露於紫外線與雨水、溫差大、動量大——TF2000 的超高耐候與寬目地對應正是為此。規劃時區分三種對象：伸縮目地（背襯材、二面接著）、打繼目地、收縮裂縫（U 形切割補修）。暴露使用免塗裝；若要塗裝，TF2000 為 Non-Bleed 但有不適用塗料，先向製造商確認。底漆 OP-2019 另售（100 ml／500 ml），採購時一併計入。', points: ['區分伸縮目地、打繼目地、裂縫。', '暴露／塗裝：塗裝時先確認塗料適用。', '底漆 OP-2019 另售。', '6 L 桶：以提桶分裝容器分裝至卡匣†。'], practice: [3], src: '超耐シーラーTF2000 商品頁（autochem.co.jp/841/）' },
    ucutC: { tag: 'U 形切割', title: '沿裂縫切出 U 形溝', short: '圓盤切割機沿裂縫兩側各切一刀（寬約 10 mm、深約 10 mm†），鑿除中間，形成 U 形溝；切粉吹除。', overview: '混凝土收縮裂縫的補修：裂縫本身太窄、邊緣脆弱，密封膠無法接著。以圓盤切割機沿裂縫切出約 10 × 10 mm† 的 U 形溝——切掉脆弱的裂縫邊緣，給密封膠一個新鮮、堅實、有厚度的接著斷面。切割時戴防塵面罩與護目鏡；切粉以吹風機或吸塵器徹底清除。', points: ['沿裂縫兩側切割，鑿除中間成 U 形溝。', '寬約 10 mm、深約 10 mm†（依裂縫寬與構造物調整）。', '切粉吹除、吸除。'], practice: [1], warning: '溝底殘留切粉會使底漆無法接著——清除至露出堅實面。', src: 'TF2000 用途「混凝土構造物裂縫的U切割補修」；一般土木補修實務†' },
    cleanC: { tag: '清掃', title: 'RC 目地・U 形溝的清掃', short: '目地與溝內的浮漿、粉塵、脫模劑刷除、吹除；確認乾燥、無油分；雨後、灑水後須完全乾燥。', overview: '土木構造物的目地常有浮漿、泥砂與脫模劑：刷除後吹除；U 形溝的切粉徹底清除。含水的下地在硬化途中釋出水蒸氣會使密封膠隆起、破裂——施工前確保完全乾燥。', points: ['刷除浮漿、泥砂；吹除切粉。', '確認乾燥、無油分。', '禁用含醇溶劑。'], warning: '下地含水 → 密封膠隆起、破裂。', src: 'OP-2019 TDS；一般土木實務†' },
    primeT: { tag: '底漆', title: '專用底漆 OP-2019 塗布（另售）', short: 'TF2000 無附屬底漆：另購 OP-2019（100 ml／500 ml）。兩側接著面與 U 形溝內面均勻刷塗，乾燥 15 分鐘以上（冬 30 分鐘以上）後填充。', overview: 'TF2000 的 6 L 桶與 320 ml 卡匣都不附底漆：專用高性能底漆 OP-2019 另行採購。塗布於目地兩側接著面與 U 形溝的三個面，均勻、無遺漏、無過量；乾燥 15–30 分鐘後填充；當日未填充的部分隔日重塗。', points: ['OP-2019 另售：100 ml、500 ml 罐。', '兩側接著面＋U 形溝內面均勻刷塗。', '乾燥 ≥ 15 min（冬 ≥ 30 min）。'], warning: '未乾燥即填充或過量塗布 → 溶劑揮發使密封膠隆起、破裂。', src: 'TF2000 商品頁（底漆 OP-2019 另售）；OP-2019 TDS 2026/1/24' },
    fillT: { tag: '填充', title: 'TF2000 的填充：寬目地與 U 形溝', short: '噴嘴抵住背襯材面慢速連續填充，不留空洞；U 形溝由溝底填起、填至膠帶面。6 L 桶以分裝容器分裝至卡匣後以打膠槍施工。', overview: '寬目地容易在背襯材兩側夾空氣：噴嘴抵住背襯材面慢速打膠，讓密封膠由底部向上填滿；U 形溝沒有背襯材，噴嘴抵住溝底連續填充。6 L 桶裝用提桶分裝容器分裝至卡匣（25 支一組），留一些供日後補修。', points: ['噴嘴抵住底部，慢速連續。', '填滿至膠帶面，不留空洞。', '桶裝 → 分裝容器 → 卡匣。'], src: 'TF2000 商品頁；提桶分裝容器商品頁' },
    inspC: { tag: '檢查', title: '土木目地的檢查與紀錄', short: '目視：飽滿、無空洞、無漏打；暴露面不需塗裝。紀錄 LOT、目地尺寸、底漆塗布與完工照片。', overview: '土木構造物的目地多半暴露：TF2000 完工後即為最終面。檢查密封膠飽滿、無空洞、無漏打、無氣泡；沾到構造物面的密封膠在硬化前擦除。紀錄密封膠 LOT、底漆 LOT 與用量、目地寬深、完工照片。', points: ['飽滿、無空洞、無漏打。', '硬化前擦除沾污。', '紀錄 LOT、尺寸、照片。'], src: '一般施工管理實務†' },
    cureC: { tag: '養生', title: '養生與硬化（數值 TBC）', short: '指觸乾燥・完全硬化時間製造商未公布：本站以同系一液聚氨酯參考值†排程（23 °C 指觸 5 h、完全 3–7 天）；通水、塗裝在完全硬化之後。', overview: 'TF2000 的硬化時間未公布於製造商網頁（TBC）：模擬器以 EXCEED／101A-NB 的 TDS 值作參考†。一液濕氣硬化型：低溫時延長；U 字溝等通水設施在完全硬化後通水；塗裝在完全硬化後並先確認塗料適用。', points: ['硬化時間：TBC（以同系參考值†排程）。', '通水、塗裝在完全硬化後。', '低溫時延長養生。'], practice: [0], src: '製造商網頁未公布；同系 TDS 參考' },
    planI: { tag: '規劃', title: '產業現場：接合部的種類與節拍', short: '鋼板搭接縫（填角）、電纜線槽與配電盒周邊（塑膠對金屬）、水密・氣密部位：速乾型 101R 一支對應；顏色白／T 灰／黑配合塗裝面。', overview: '工業用途的密封：機械外殼、鋼製箱體、折板・鋼板牆的搭接縫，電纜線槽、配電盒等塑膠部品與金屬面的接合，以及水密・氣密部位。101R 是為產業用途開發的速乾型標準品：硬化快，不拖慢節拍；對各種金屬到塑膠、玻璃皆適用。無附屬底漆——特殊基材先做接著試驗。', points: ['搭接縫 → 填角；線槽・配電盒 → 周邊填角。', '顏色：白、T 灰、黑。', '特殊基材先做接著試驗†。'], practice: [2], src: 'シーラー101R 商品頁（autochem.co.jp/981/）' },
    cleanI: { tag: '脫脂', title: '金屬・塑膠面的脫脂清掃', short: '搭接縫邊緣、線槽與配電盒周邊以溶劑擦拭脫脂（油分、指紋、粉塵）；擦拭後讓溶劑完全揮發。', overview: '產業現場的鋼板與塑膠部品常有防鏽油、加工油與粉塵：以溶劑浸潤的布擦拭脫脂，再以乾布擦乾；讓溶劑完全揮發後才貼膠帶、打膠。鍍鋅・塗裝鋼板不可用會侵蝕塗膜的溶劑。', points: ['溶劑擦拭脫脂，乾布擦乾。', '溶劑完全揮發後再施工。', '禁用含醇溶劑。'], src: '一般工業密封實務†' },
    tapeI: { tag: '遮蔽膠帶', title: '填角的遮蔽', short: '搭接縫：膠帶貼在下板側，留出填角寬度；線槽・配電盒：膠帶貼在鋼板側。上板・線槽本體側不貼。', overview: '填角只有一側是平面：搭接縫的膠帶貼在下板上，與板端平行、留出約 10 mm† 的填角寬；線槽與配電盒周邊的膠帶貼在鋼板上。膠帶壓實、無浮起。', points: ['下板側／鋼板側貼膠帶。', '留出填角寬（約 10 mm†）。', '壓實、無浮起。'], practice: [1], src: '一般工業密封實務†' },
    fillR: { tag: '填充', title: '101R 的填角打膠', short: '沿搭接邊緣與線槽周邊連續打出三角形填角（約 10 × 8 mm 本例）：噴嘴抵住板端與下板的夾角，一次打足。', overview: '噴嘴斜抵在上板端與下板面的夾角，連續推進打出填角；線槽與配電盒沿周邊一圈連續打膠，轉角不中斷。速乾型：一次打完一段立即抹平。', points: ['噴嘴抵住夾角，連續推進。', '轉角不中斷。', '一段打完立即抹平。'], src: '101R 商品頁（用途）；一般實務†' },
    toolI: { tag: '抹刀壓平', title: '填角的抹平', short: '以抹刀把填角壓成一致的三角斷面，密貼板端與下板；表面硬化前撕除膠帶。', overview: '抹刀沿填角一次拉過，壓出一致的三角斷面、趕出氣泡，兩面密貼；速乾型須在表面硬化前撕除膠帶。', points: ['抹刀一次拉過，斷面一致。', '兩面密貼、無氣泡。', '表面硬化前撕膠帶。'], src: '一般實務†' },
    inspI: { tag: '檢查', title: '水密・氣密的確認', short: '填角連續、無斷點、無氣泡；水密部位可做淋水試驗†；塑膠部品周邊確認無剝離。', overview: '目視填角連續無斷點；水密・氣密要求的箱體可在硬化後淋水或加壓確認†；線槽與配電盒周邊確認無剝離。', points: ['連續、無斷點、無氣泡。', '淋水・加壓確認†。', '周邊無剝離。'], practice: [1], src: '一般實務†' },
    cureI: { tag: '養生', title: '速乾型的硬化（數值 TBC）', short: '101R 為速乾型，硬化時間未公布（TBC）：本站以同系一液聚氨酯參考值†排程；出貨・振動負載在硬化後。', overview: '101R 的硬化時間未公布於製造商網頁（TBC）；模擬器以同系一液 PU 的 TDS 值作參考†，速乾型的實際時間可能更短。硬化後成為高伸度的橡膠彈性體，之後才承受振動與衝擊。', points: ['硬化時間：TBC（以同系參考值†）。', '硬化後再承受振動負載。'], practice: [0], src: '製造商網頁未公布；同系 TDS 參考' },
    planU: { tag: '規劃', title: '翻新塗裝前：補填對象的調查', short: '釘頭・螺絲孔的凹陷、板材缺角、裂縫逐一標記；小面積用 170 g 軟管，釘頭多、面積大用 320 ml 卡匣＋打膠槍。', overview: '窯業系外牆板翻新塗裝前，面漆遮不住的缺陷先補填：釘頭・螺絲孔、缺角、裂縫、大目地的修復。フラットパテ（軟管，附 20 ml 底漆）適合小面積；アドハー3500（卡匣，每箱附 100 ml 底漆 × 2）以打膠槍施工，效率高。', points: ['標記釘頭、缺角、裂縫。', '軟管／卡匣依數量選擇。', '確認面漆相容性。'], src: 'フラットパテ／アドハー3500 商品頁' },
    cleanU: { tag: '清掃', title: '補填處的清掃', short: '釘頭周圍的鏽、粉塵、舊塗膜浮起刷除；裂縫邊緣的脆弱部除去；確認乾燥。', overview: '補填處的粉塵與浮起的舊塗膜會使補土剝離：釘頭周圍以刷、砂紙清理，裂縫邊緣的脆弱部除去；確認乾燥、無油分。', points: ['刷除粉塵、浮起塗膜。', '裂縫邊緣脆弱部除去。', '確認乾燥。'], src: '一般塗裝下地處理實務†' },
    primeU: { tag: '底漆', title: '附屬專用底漆的點塗', short: '補填處以附屬小刷薄塗專用底漆（軟管附 20 ml；卡匣每箱附 100 ml × 2），乾燥後補填。', overview: '補土的接著靠附屬的專用底漆：釘頭・螺絲孔、裂縫、缺角逐點薄塗，乾燥後再補填。用量少，切勿過量堆積。', points: ['逐點薄塗。', '乾燥後補填。', '不過量。'], src: 'フラットパテ商品頁（付属品 20 ml 專用底漆）' },
    fillU: { tag: '補填', title: '補土的補填：釘頭與裂縫', short: '軟管或打膠槍逐點擠入釘頭・螺絲孔，略高於板面；裂縫沿線擠入填滿；缺角堆填成型。', overview: '釘頭與螺絲孔：噴嘴抵住凹陷擠入補土至略高於板面；裂縫：沿線連續擠入；缺角：堆填後成型。一液型、收縮少：不必分層多次補填。', points: ['逐點擠入，略高於板面。', '裂縫沿線連續。', '缺角堆填成型。'], src: 'フラットパテ商品頁（特長）' },
    toolU: { tag: '抹平', title: '抹刀抹平：與板面齊', short: '以抹刀把補土抹平與板面齊，多餘的刮除；硬化後幾乎不收縮，補填處平整。', overview: '補填後立即以抹刀抹平：釘頭處抹成與板面齊的圓面，裂縫沿線刮平；硬化後幾乎不收縮，不必二次補填。沾到板面的補土在硬化前擦除。', points: ['抹平與板面齊。', '多餘刮除、擦除。', '硬化後不收縮。'], src: 'フラットパテ商品頁（特長）' },
    paintU: { tag: '塗裝', title: '硬化後的整面塗裝', short: '補土硬化後整面塗裝：特殊聚氨酯聚合物與大多數面漆相容、附著極佳；不含可塑劑，面漆不變色、不積塵。', overview: '補土完全硬化後進行翻新塗裝：面漆直接塗在補土上，附著極佳；因不含可塑劑，塗膜不會經時變色或發黏積塵。硬化時間未公布（TBC）：依塗裝規範確認。', points: ['硬化後整面塗裝。', '面漆附著極佳。', '不污染面漆。'], src: 'フラットパテ商品頁（面漆的附著性）' },
    inspU: { tag: '檢查', title: '補填處的檢查', short: '塗裝後確認補填處平整無痕、無收縮凹陷、無龜裂；釘頭無漏補。', overview: '塗裝後補填處應平整無痕：確認無收縮凹陷、無龜裂、釘頭無漏補；有遺漏者補填後局部補塗。', points: ['平整無痕。', '無凹陷、無龜裂。', '無漏補。'], src: '一般實務†' }
  };
  /* ================================================================ English ================================================================ */
  S.en.civil = { name: 'Expansion joints and U-cut crack repair on RC structures (civil engineering)', problem: 'The joints of bridges, piers, parapets, retaining walls, culverts and U-channels sit in sun, rain and temperature swings for decades: an ordinary sealant hardens and cracks, water gets in, and reinforcement corrosion and frost damage spread from there. Expansion joints are wide and move a lot — more than building sealants follow. A shrinkage crack left alone becomes the start of leaks and spalling.', solution: '{TF2000}: a one-component polyurethane registered with NETIS (KT-190076-VE) and listed in the agricultural-waterworks repair guidebook — very high weathering, high durability, wide joints; exposed use is its strongest point, and it is non-bleed under paint. Expansion joints are filled over a backer rod; shrinkage cracks are U-cut along the crack, cleaned, primed with the dedicated {OP2019} (sold separately) and filled flush. The 6 L pail is decanted into cartridges with the pail-refill cartridges.' };
  S.en.ind = { name: 'Steel-sheet lap seams and cable moulding (industry)', problem: 'The lap seams of machine housings, steel cabinets, folded-plate and steel-sheet walls loosen under vibration and temperature change, and rain and dust get through; the joints between plastic parts — cable moulding, junction boxes — and the metal face are the weak points of water- and airtightness. Industrial work runs to a takt: a slow-curing sealant holds up assembly and shipping.', solution: '{R101}: the quick-drying standard grade developed for industry on the manufacturer\'s polyurethane technology — fast cure, a high-elongation rubber after cure that absorbs the vibration and shock of the joint, and good following of thermal movement; suitable for metals, plastics and glass. Lap seams get a fillet along the edge of the upper sheet; moulding and boxes a fillet round their perimeter. White, T-grey and black to suit painted faces.' };
  S.en.putty = { name: 'Nail heads and cracks in siding: putty before repainting (architectural putties)', problem: 'Before fibre-cement siding is repainted, the dimples of nail heads and screw holes, chipped corners and cracks must be filled: paint will not hide them, and they take in water and lift the coating later. An ordinary filler shrinks back as it cures, and a plasticised one stains the finish and leaves it tacky and dusty.', solution: '{FLATP} (170 g tube with 20 ml primer) / {AD3500} (320 ml cartridge, 100 ml primer ×2 per box): a one-component flexible urethane putty — almost no shrinkage, so the repair stays flat; no plasticiser, so the finish is not stained; compatible with most finishes and bonds to them very well. Clean → the supplied primer → fill → flatten with a spatula → paint the whole face after cure.' };
  X.en.layers = { sealTF: ['Sealant (civil, exposed grade)', 'Filled slowly from the rod face, pressed in and tooled; left exposed, or painted (some paints not suitable)', '20 wide × 15 deep (this example); U-cut about 10 × 10 mm', '320 ml ÷ (width × depth) ÷ 1.2 m per cartridge †; the 6 L pail decanted into cartridges', 'Tack-free and full cure: not published (TBC); water and paint after full cure', 'One-component polyurethane; grey / light grey; NETIS KT-190076-VE'], sealR: ['Sealant (industrial, quick-drying)', 'A fillet along the lap edge and round the moulding, tooled to a uniform triangle', 'Fillet about 10 × 8 mm (this example)', '320 ml ÷ (width × depth ÷ 2) ÷ 1.2 m per cartridge † (triangular section)', 'Quick-drying: cure times not published (TBC); tape off before skinning', 'Polyurethane; white / T-grey / black; JSIA F☆☆☆☆'], putty: ['Flexible urethane putty', 'Nail heads and screw holes filled one by one, cracks along their length; flattened flush with the board', 'Nail heads: the dimple; crack: U-groove 10 × 8 mm (this example)', '170 g tube / 320 ml cartridge; quantity by the size of the dimples (not published)', 'Almost no shrinkage after cure; cure time not published (TBC); painted after cure', 'One-component urethane putty; no plasticiser; F☆☆☆☆ / 4VOC'], primP: ['Putty primer (supplied)', 'Dabbed on the repair with the small brush supplied, filled after it dries', 'Thin', '20 ml (with the tube) / 100 ml ×2 (per box of cartridges)', 'Filled after it dries (time not published, TBC)', 'Dedicated primer'] };
  X.en.stages = { ucut: 'U-cut' };
  X.en.co = {
    civil: [['Expansion joint and U-groove', 'The expansion joint is 20 mm wide and 15 mm deep (this example): the rod gives two-sided adhesion and the right thickness. The shrinkage crack is cut with a disc cutter into a U-groove of about 10 × 10 mm — the weak crack edges go, and the sealant gets a fresh, sound section with thickness.'], ['The primer is sold separately', 'Neither the 6 L pail nor the 320 ml cartridge of TF2000 comes with primer: the dedicated high-performance primer OP-2019 (100 ml / 500 ml cans) is bought separately, brushed on and left at least 15 minutes before filling.'], ['Exposed, no paint needed', 'Civil-engineering joints are mostly left exposed: that is what TF2000\'s very high weathering is for. If painted (parapets, say) it is a non-bleed grade, but some paints are not suitable — check with the manufacturer first.']],
    ind: [['A lap seam: a fillet, not a joint', 'A lap seam has no joint cavity: the sealant is run as a fillet along the edge of the upper sheet, covering the sheet end and bonding to the lower sheet — no backer rod, tape on the lower sheet only; the spatula presses the fillet to a uniform section.'], ['Plastic on metal', 'Cable moulding (PVC) and a junction box fixed to the steel sheet: a fillet round the perimeter. 101R suits metals, plastics and glass; the surfaces are degreased with a solvent wipe before taping.'], ['Quick-drying, the takt holds', '101R is quick-drying: fast cure, no waiting on the line; after cure a high-elongation rubber that absorbs vibration and shock. No primer is supplied — run an adhesion test first on unusual substrates.']],
    putty: [['Nail heads and chips', 'Before repainting, the nail heads and screw holes, chips and cracks of the siding are filled first: the putty hardly shrinks, the repair stays flat and the finish shows no mark.'], ['The supplied primer, then the fill', 'The tube comes with 20 ml of primer and a small brush; each box of cartridges with 100 ml ×2: the repair is primed first, filled from the tube or the gun after the primer dries, and flattened flush with the spatula.'], ['No staining of the finish', 'No plasticiser: nothing bleeds out to discolour the finish or leave it tacky and dusty; the special urethane polymer suits most finishes — paint the whole face after cure.']]
  };
  X.en.microSub = { civil: 'The pores of the concrete and the primer: OP-2019 soaks into the surface pores and cures, and TF2000 fuses to it; the cut faces of the U-groove are fresh, sound bonding faces.', ind: '(A fillet seal: no joint section at micro scale in this scenario.)', putty: '(Spot repairs: no joint section at micro scale in this scenario.)' };
  X.en.lb = { ucut: 'U-groove: about 10 × 10 mm', cutterD: 'Disc cutter along the crack', crack: 'Shrinkage crack (where leaks start)', dustC: 'Cuttings blown and vacuumed out', coping: 'RC parapet / retaining wall', ej: 'Expansion joint: 20 wide · 15 deep', prim19s: 'Primer OP-2019 (sold separately)', pail: '6 L pail → refill cartridges', steel: 'Painted steel sheet (lapped)', lap: 'Lap seam: upper sheet over lower', mould: 'Cable moulding (PVC)', jbox: 'Junction box (PVC)', rag: 'Solvent wipe (degrease)', fillet: 'Fillet: covers the sheet end, bonds the lower sheet', nail: 'Nail-head / screw-hole dimple', chip: 'Chip / crack', primP: 'Supplied primer: dabbed on', dab: 'Putty: filled spot by spot', flat: 'Spatula: flush with the board', exposed: 'Exposed use: no paint', tgrey: 'T-grey to suit the painted face', paintU: 'Whole face painted after cure' };
  X.en.opts = [['TF2000', 'オートン超耐シーラーTF2000 · civil engineering', 'NETIS KT-190076-VE · very high weathering, high durability · wide joints · exposed or painted · primer OP-2019 (sold separately)'], ['R101', 'オートンシーラー101R · industry', 'Quick-drying · high elasticity · metals, plastics, glass · white / T-grey / black · JSIA F☆☆☆☆ · no primer supplied'], ['FLATP', 'オートンフラットパテ · 170 g tube', 'Flexible urethane putty · little shrinkage · non-bleed · paintable · 20 ml primer supplied'], ['AD3500', 'オートンアドハー3500 · 320 ml cartridge', 'The same putty for the gun · 100 ml primer ×2 per box · F☆☆☆☆ / 4VOC']];
  X.en.kinds = [['civil', 'Civil expansion joint (RC)'], ['ucut', 'U-cut crack repair'], ['ind', 'Steel lap seam / moulding (fillet)']];
  X.en.simTl = { ucut: ['U-cut', 'Groove cut along the crack, cuttings blown out'] };
  X.en.items = { TF2000: 'オートン超耐シーラーTF2000 320 ml cartridge', TF2000P: 'オートン超耐シーラーTF2000 6 L pail', R101: 'オートンシーラー101R 320 ml cartridge', FLATP: 'オートンフラットパテ 170 g tube', AD3500: 'オートンアドハー3500 320 ml cartridge', OP2019S: 'AUTON PRIMER OP-2019 500 ml (sold separately)' };
  X.en.packs = { TF2000: 'pcs (10 per box)', TF2000P: 'pails (2 per box)', R101: 'pcs (25 per box)', FLATP: 'pcs', AD3500: 'pcs (10 per box)', OP2019S: 'cans' };
  X.en.refNote = '† TF2000, 101R and the putties: the manufacturer\'s pages print no tack-free or full-cure times — the simulator runs on the TDS values of the sister 1K polyurethanes (EXCEED / 101A-NB) as reference values, for rough scheduling only; refer to the manufacturer\'s current documents.';
  P.en.TF2000 = { sub: 'One-component polyurethane sealant (civil engineering, NETIS-registered)', pack: '6 L pail ×2 per box; 320 ml cartridge ×10 per box (no accessories; primer OP-2019 sold separately in 100 ml / 500 ml cans)', colour: 'Grey, light grey (2 colours)', kind: 'One-component polyurethane', use: 'Joints of irrigation channels (U-channels and the like), bridges and piers, concrete parapets, precast concrete products (box culverts, Hume pipes, manholes, utility tunnels, fire-water tanks) and other concrete structures; U-cut repair of cracks in concrete structures.',
    role: 'The sealant for civil-engineering joints: very high weathering and resistance to exposure are its strongest points; good paint adhesion and non-bleed, so it also serves under paint; easy to work and usable in wide joints. NETIS-registered (KT-190076-VE), conforming to the Sōpuro quality standard for injection and filling materials, listed in the agricultural-waterworks repair guidebook.', areas: ['Joints of irrigation channels (U-channels and the like)', 'Joints of bridges and piers', 'Concrete parapet joints', 'Joints of precast concrete products (box culverts, Hume pipes, manholes, utility tunnels, fire-water tanks)', 'U-cut repair of cracks in concrete structures', 'Other joints of concrete structures'], adv: ['Very high weathering, high durability: exceptionally weather-resistant, stands exposure (manufacturer\'s rating: weathering ◎, durability ○)', 'Wide joints', 'Good paint adhesion, non-bleed: also suited as a substrate for paint (some paints not suitable — ask first)', 'Easy to work, many uses'], feat: ['NETIS-registered (KT-190076-VE)', 'Conforms to the Sōpuro quality standard for injection and filling materials', 'Listed in the agricultural-waterworks repair guidebook', 'Dedicated high-performance primer OP-2019 (sold separately): urethane type, for a wide range of substrates'],
    data: [['Type', 'One-component polyurethane'], ['Weathering / durability', '◎ / ○ (manufacturer\'s page)'], ['Paint', '◎ non-bleed — some paints not suitable; ask before painting'], ['Registration', 'NETIS KT-190076-VE; Sōpuro quality standard; agricultural-waterworks repair guidebook'], ['Hardness, modulus, elongation', 'Not published on the manufacturer\'s page (TBC)'], ['Tack-free, full cure', 'Not published (TBC); the simulator uses the sister 1K PU values †'], ['Primer', 'OP-2019 dedicated high-performance primer (sold separately): 100 ml and 500 ml cans'], ['Packaging', '6 L pail ×2 per box; 320 ml cartridge ×10 per box']],
    tests: [['NETIS', 'KT-190076-VE (New Technology Information System)'], ['Sōpuro', 'Conforms to the quality standard for injection and filling materials'], ['Guidebook', 'Listed in the agricultural-waterworks repair guidebook']], safety: [['Paint', 'Some paints are not suitable: confirm with the manufacturer before painting'], ['Primer', 'None supplied: buy OP-2019; fill 15–30 min after priming (OP-2019 TDS)'], ['SDS', 'Manufacturer\'s SDS (sealants)']] };
  P.en.R101 = { sub: 'Quick-drying, high-elasticity polyurethane sealant (industrial standard grade)', pack: '320 ml cartridge ×25 per box (no accessories)', colour: 'White, T-grey, black (paste, 3 colours)', kind: 'Polyurethane (component type not stated)', use: 'Steel-sheet seams, watertight and airtight details, cable moulding, joint sealing of metals to plastics.',
    role: 'A quick-drying, multi-purpose sealant developed for industry on the manufacturer\'s polyurethane technology: fast cure for work that must move quickly; after cure a high-elongation rubber that absorbs the vibration and shock of the bonded joint; follows the thermal movement of parts and keeps a high seal. Suits metals, plastics and glass.', areas: ['Steel-sheet seams', 'Watertight and airtight details', 'Cable moulding', 'Joint sealing of metals to plastics'], adv: ['Quick-drying: fast cure, quick work', 'High elasticity: a high-elongation rubber that absorbs vibration and shock', 'Follows thermal movement', 'Multi-purpose: metals, plastics, glass'], feat: ['JSIA F☆☆☆☆', 'White, T-grey and black paste', '320 ml cartridge ×25 per box'],
    data: [['Cure', 'Quick-drying (figures not published, TBC); the simulator uses the sister 1K PU values †'], ['Registration', 'JSIA F☆☆☆☆'], ['Colours', 'White, T-grey, black (paste)'], ['Primer', 'None supplied; confirm adhesion on the substrate first'], ['Physical data', 'Not published on the manufacturer\'s page (TBC)'], ['Packaging', '320 ml cartridge ×25 per box']],
    safety: [['Degreasing', 'Remove oil and dust from metal and plastic faces first'], ['Alcohols', 'Keep uncured 1K polyurethane away from alcohols: silicone and MS work separately'], ['SDS', 'Manufacturer\'s SDS (sealants)']] };
  P.en.FLATP = { sub: 'One-component flexible urethane putty (facade repair, tube)', pack: '170 g tube (with 20 ml dedicated primer, nozzle, cap, brush)', colour: 'Not published (TBC)', kind: 'Urethane putty (one-component, special urethane polymer)', use: 'Crack repair of concrete, mortar and fibre-cement siding; cracks, chips and wide joints in renovation work; filling nail heads and the like on siding, repairing chips and cracks; other repairs and fillings.',
    role: 'A flexible elastic putty for exterior components: repairs cracks and chips in facade materials and fills screw holes and nail heads. Almost no shrinkage after cure, so the repair stays flat; one-component, easy to work, saves time; no plasticiser, so it does not stain the finish. A tube with its own primer and brush — ready for small repairs.', areas: ['Crack repair of concrete, mortar and fibre-cement siding', 'Cracks, chips and wide joints in renovation work', 'Filling nail heads on siding; repairing chips and cracks', 'Other repairs and fillings'], adv: ['Flexible: an elastic putty for exterior components', 'Little shrinkage: almost none after cure, the repair stays flat', 'Paintable: compatible with the usual finishes', 'Non-bleed: no plasticiser, no staining of the finish'], feat: ['Excellent adhesion of the finish: a special urethane polymer compatible with most finishes', 'No plasticiser to stain the coating over time: no discolouration, no dust pick-up', 'Durable: water- and heat-resistant after cure, long-lasting', 'F☆☆☆☆ / JAIA 4VOC compliant'],
    data: [['Composition', 'One-component urethane putty (special urethane polymer)'], ['Shrinkage', 'Almost none after cure'], ['Plasticiser', 'None (non-bleed)'], ['Adhesion of finishes', 'Excellent (most finishes)'], ['Registration', 'F☆☆☆☆, JAIA 4VOC compliant'], ['Cure time, application temperature', 'Not published on the manufacturer\'s page (TBC)'], ['Packaging', '170 g tube + 20 ml primer, nozzle, cap, brush']],
    safety: [['Primer', 'Prime the repair with the supplied primer and fill after it dries'], ['Painting', 'Paint after cure; check the finish for compatibility first'], ['SDS', 'Manufacturer\'s SDS']] };
  P.en.AD3500 = { sub: 'One-component flexible urethane putty (facade repair, cartridge)', pack: '320 ml cartridge ×10 per box (with 100 ml primer ×2 cans and 1 brush)', colour: 'Not published (TBC)', kind: 'Urethane putty (one-component, special urethane polymer)', use: 'As フラットパテ: crack repair of concrete, mortar and fibre-cement siding; nail-head filling; chips and cracks.',
    role: 'The cartridge version of フラットパテ: the same flexible elastic putty applied with a gun, for renovations with many nail heads and larger areas; each box comes with 100 ml primer ×2 and a brush.', areas: ['Crack repair of concrete, mortar and fibre-cement siding', 'Cracks, chips and wide joints in renovation work', 'Filling nail heads on siding; repairing chips and cracks', 'Other repairs and fillings'], adv: ['Flexible elastic putty', 'Little shrinkage, stays flat', 'Paintable, non-bleed', 'Gun application: efficient'], feat: ['Excellent adhesion of the finish: a special urethane polymer', 'No plasticiser: no staining of the finish', 'Water- and heat-resistant', 'F☆☆☆☆ / JAIA 4VOC compliant'],
    data: [['Composition', 'One-component urethane putty (special urethane polymer)'], ['Shrinkage', 'Almost none after cure'], ['Plasticiser', 'None (non-bleed)'], ['Registration', 'F☆☆☆☆, JAIA 4VOC compliant'], ['Cure time, application temperature', 'Not published on the manufacturer\'s page (TBC)'], ['Packaging', '320 ml cartridge ×10 per box + 100 ml primer ×2, brush ×1']],
    safety: [['Primer', 'Prime with the supplied primer, fill after it dries'], ['Painting', 'Paint after cure; check the finish for compatibility first'], ['SDS', 'Manufacturer\'s SDS']] };
  P.en.PRIMP = { sub: 'Putty primer (supplied with the putty)', pack: 'フラットパテ: 20 ml with the tube; アドハー3500: 100 ml ×2 cans per box', colour: '—', kind: 'Dedicated primer', use: 'Adhesion treatment of the repair: a thin coat with the small brush supplied, filled after it dries.', role: 'The adhesion of the putty: nail heads, screw holes, cracks and chips are dabbed with primer first and filled after it dries.', areas: ['Every putty repair'], adv: ['Supplied with the putty', 'Dabbed on with the small brush, little used'], feat: ['Matched to フラットパテ / アドハー3500'], data: [['Drying time', 'Not published (TBC)'], ['Packaging', '20 ml (with the tube) / 100 ml ×2 (per box of cartridges)']], safety: [['Drying', 'Filling before it dries weakens adhesion'], ['SDS', 'Manufacturer\'s SDS']] };
  T.en = {
    planC: { tag: 'Planning', title: 'RC structures: joint types and movement', short: 'Expansion joints (20 wide, 15 deep in this example), construction joints and shrinkage cracks are treated differently: expansion joints need a rod and two-sided adhesion; cracks are U-cut, then filled. Decide exposed or painted.', overview: 'Bridges and piers, parapets, retaining walls, culverts, U-channels: the joints sit in sun and rain with large temperature swings and movement — the very high weathering and wide-joint capability of TF2000 are for this. Distinguish three targets: expansion joints (rod, two-sided adhesion), construction joints, shrinkage cracks (U-cut repair). Exposed use needs no paint; if painted, TF2000 is non-bleed but some paints are unsuitable — check with the manufacturer. The primer OP-2019 is sold separately (100 ml / 500 ml): put it on the order.', points: ['Separate expansion joints, construction joints and cracks.', 'Exposed or painted: check paint suitability first.', 'Primer OP-2019 sold separately.', '6 L pail: decant into cartridges with the refill cartridges †.'], practice: [3], src: 'TF2000 product page (autochem.co.jp/841/)' },
    ucutC: { tag: 'U-cut', title: 'Cut a U-groove along the crack', short: 'A disc cutter runs one cut on each side of the crack (about 10 mm wide, 10 mm deep †), the middle is chiselled out into a U-groove; cuttings blown out.', overview: 'Repair of a shrinkage crack: the crack itself is too narrow and its edges too weak for a sealant to bond. A disc cutter opens a U-groove of about 10 × 10 mm † along the crack — the weak edges go, and the sealant gets a fresh, sound section with thickness. Dust mask and goggles while cutting; blow or vacuum the cuttings out completely.', points: ['Cut along both sides of the crack, chisel out the middle.', 'About 10 mm wide, 10 mm deep † (adjusted to the crack and the structure).', 'Blow and vacuum the cuttings out.'], practice: [1], warning: 'Cuttings left in the groove stop the primer bonding — clean down to sound concrete.', src: 'TF2000 use "U-cut repair of cracks in concrete structures"; general civil repair practice †' },
    cleanC: { tag: 'Cleaning', title: 'Cleaning the RC joint and the U-groove', short: 'Laitance, dust and release agent brushed and blown out of the joint and the groove; dry and oil-free; fully dry after rain or washing.', overview: 'Civil joints carry laitance, silt and release agent: brush, then blow out; remove every cutting from the U-groove. A damp substrate releases water vapour as the sealant cures and lifts or splits it — make sure it is fully dry before work.', points: ['Brush off laitance and silt; blow out cuttings.', 'Dry, oil-free.', 'No alcohol-based solvents.'], warning: 'Moisture in the substrate → the sealant lifts and splits.', src: 'OP-2019 TDS; general civil practice †' },
    primeT: { tag: 'Primer', title: 'Primer OP-2019 (sold separately)', short: 'TF2000 comes without primer: buy OP-2019 (100 ml / 500 ml). Brush it evenly on both bonding faces and inside the U-groove, let it dry at least 15 minutes (30 in winter), then fill.', overview: 'Neither the 6 L pail nor the 320 ml cartridge of TF2000 includes primer: the dedicated high-performance primer OP-2019 is bought separately. Brushed on both bonding faces of the joint and the three faces of the U-groove, evenly, with no gaps and no excess; filled after 15–30 minutes; anything not filled the same day is re-primed the next.', points: ['OP-2019 sold separately: 100 ml, 500 ml cans.', 'Both faces + inside the U-groove, evenly.', 'Dry ≥ 15 min (winter ≥ 30 min).'], warning: 'Filling before it dries, or too thick → the solvent lifts and splits the sealant.', src: 'TF2000 product page (primer OP-2019 sold separately); OP-2019 TDS 2026/1/24' },
    fillT: { tag: 'Filling', title: 'Filling TF2000: the wide joint and the U-groove', short: 'Nozzle on the rod face, slow and continuous, no voids; the U-groove filled from the bottom up to the tape. The 6 L pail is decanted into cartridges with the refill cartridges and run from the gun.', overview: 'A wide joint traps air beside the rod: keep the nozzle on the rod face and move slowly so the sealant fills from the bottom up; the U-groove has no rod — nozzle on the groove bottom, continuous. The 6 L pail is decanted into cartridges (the refill set of 25), keeping some for later repairs.', points: ['Nozzle on the bottom, slow and continuous.', 'Fill to the tape, no voids.', 'Pail → refill cartridges → gun.'], src: 'TF2000 product page; pail-refill cartridge product page' },
    inspC: { tag: 'Inspection', title: 'Inspection and records of civil joints', short: 'Visual: full, no voids, nothing missed; exposed faces need no paint. Record lots, joint sizes, priming and completion photographs.', overview: 'Civil joints are mostly left exposed: TF2000 is the finished face. Check that the sealant is full, free of voids and bubbles and nothing is missed; wipe sealant off the structure before it cures. Record the sealant lot, the primer lot and quantity, joint width and depth, completion photographs.', points: ['Full, no voids, nothing missed.', 'Wipe off smears before cure.', 'Record lots, sizes, photographs.'], src: 'General site-management practice †' },
    cureC: { tag: 'Curing', title: 'Curing (figures TBC)', short: 'Tack-free and full-cure times are not published: this site schedules on the sister 1K polyurethane reference values † (23 °C: tack-free 5 h, full cure 3–7 days); water and paint after full cure.', overview: 'The cure times of TF2000 are not on the manufacturer\'s page (TBC): the simulator uses the EXCEED / 101A-NB TDS values as reference †. One-component moisture cure: longer in the cold; water channels are filled after full cure; painting after full cure, with the paint checked for suitability first.', points: ['Cure time: TBC (scheduled on sister reference values †).', 'Water and paint after full cure.', 'Longer curing in the cold.'], practice: [0], src: 'Not published by the manufacturer; sister TDS as reference' },
    planI: { tag: 'Planning', title: 'The industrial site: joint types and takt', short: 'Steel-sheet lap seams (fillet), the perimeter of cable moulding and junction boxes (plastic on metal), watertight and airtight details: one quick-drying grade, 101R, in white / T-grey / black to suit the painted face.', overview: 'Industrial sealing: the lap seams of machine housings, steel cabinets, folded-plate and steel-sheet walls; the joints of plastic parts — cable moulding, junction boxes — to the metal face; watertight and airtight details. 101R is the quick-drying standard grade developed for industry: fast cure that keeps the takt; suits metals, plastics and glass. No primer supplied — run an adhesion test on unusual substrates.', points: ['Lap seam → fillet; moulding and box → fillet round the perimeter.', 'Colours: white, T-grey, black.', 'Adhesion test on unusual substrates †.'], practice: [2], src: '101R product page (autochem.co.jp/981/)' },
    cleanI: { tag: 'Degreasing', title: 'Degreasing the metal and plastic faces', short: 'The lap edge and the perimeter of the moulding and box are wiped with solvent (oil, fingerprints, dust); the solvent is left to flash off completely.', overview: 'Steel sheet and plastic parts on an industrial site carry rust-preventive oil, machining oil and dust: wipe with a solvent-wetted rag, then dry with a clean one; let the solvent flash off completely before taping and gunning. Do not use solvents that attack the paint of coated or galvanised sheet.', points: ['Solvent wipe, then a dry rag.', 'Let the solvent flash off before work.', 'No alcohol-based solvents.'], src: 'General industrial sealing practice †' },
    tapeI: { tag: 'Masking tape', title: 'Masking a fillet', short: 'Lap seam: tape on the lower sheet, leaving the fillet width; moulding and box: tape on the steel. No tape on the upper sheet or on the moulding itself.', overview: 'A fillet has only one flat side: at the lap seam the tape goes on the lower sheet, parallel to the sheet end, leaving about 10 mm † of fillet width; round the moulding and the box the tape goes on the steel. Pressed down, no lifting.', points: ['Tape on the lower sheet / on the steel.', 'Leave the fillet width (about 10 mm †).', 'Pressed down, no lifting.'], practice: [1], src: 'General industrial sealing practice †' },
    fillR: { tag: 'Filling', title: 'Gunning the 101R fillet', short: 'A continuous triangular fillet (about 10 × 8 mm in this example) along the lap edge and round the moulding: nozzle in the angle between the sheet end and the lower sheet, laid in one pass.', overview: 'The nozzle sits at an angle in the corner between the upper sheet\'s end and the lower sheet\'s face and moves on continuously; round the moulding and the box the bead runs the whole perimeter without stopping at corners. Quick-drying: tool each length as soon as it is laid.', points: ['Nozzle in the angle, continuous.', 'No stops at corners.', 'Tool each length at once.'], src: '101R product page (uses); general practice †' },
    toolI: { tag: 'Tooling', title: 'Tooling the fillet', short: 'The spatula presses the fillet to a uniform triangle, tight against the sheet end and the lower sheet; the tape comes off before the surface skins.', overview: 'One pull of the spatula along the fillet gives a uniform triangular section, drives out air and seats both faces; with a quick-drying grade the tape must come off before the surface skins.', points: ['One pull, uniform section.', 'Both faces seated, no bubbles.', 'Tape off before skinning.'], src: 'General practice †' },
    inspI: { tag: 'Inspection', title: 'Checking water- and airtightness', short: 'The fillet continuous, no breaks, no bubbles; a hose test on watertight details †; no lifting round the plastic parts.', overview: 'Check by eye that the fillet is continuous without breaks; a cabinet that must be watertight or airtight can be hose-tested or pressure-tested after cure †; check round the moulding and the box for lifting.', points: ['Continuous, no breaks, no bubbles.', 'Hose or pressure test †.', 'No lifting at the perimeter.'], practice: [1], src: 'General practice †' },
    cureI: { tag: 'Curing', title: 'Cure of a quick-drying grade (figures TBC)', short: '101R is quick-drying; its cure times are not published (TBC): this site schedules on the sister 1K polyurethane reference values †; shipping and vibration loads after cure.', overview: 'The cure times of 101R are not on the manufacturer\'s page (TBC); the simulator uses the sister 1K PU TDS values as reference † — a quick-drying grade may well be faster. After cure it is a high-elongation rubber, and only then carries vibration and shock.', points: ['Cure time: TBC (sister reference values †).', 'Vibration loads after cure.'], practice: [0], src: 'Not published by the manufacturer; sister TDS as reference' },
    planU: { tag: 'Planning', title: 'Before repainting: survey of the repairs', short: 'Nail-head and screw-hole dimples, chipped boards and cracks marked one by one; the 170 g tube for small areas, the 320 ml cartridge with the gun where there are many nail heads.', overview: 'Before fibre-cement siding is repainted, the defects paint will not hide are filled first: nail heads and screw holes, chips, cracks, the repair of wide joints. フラットパテ (tube, with 20 ml primer) suits small areas; アドハー3500 (cartridge, 100 ml primer ×2 per box) runs from the gun and is efficient on large jobs.', points: ['Mark nail heads, chips, cracks.', 'Tube or cartridge by the count.', 'Check the finish for compatibility.'], src: 'フラットパテ / アドハー3500 product pages' },
    cleanU: { tag: 'Cleaning', title: 'Cleaning the repairs', short: 'Rust, dust and lifting old paint brushed off round the nail heads; weak crack edges removed; dry.', overview: 'Dust and lifting old paint under a repair make the putty peel: brush and sand round the nail heads, cut back the weak edges of cracks; dry and oil-free.', points: ['Brush off dust and lifting paint.', 'Remove weak crack edges.', 'Dry.'], src: 'General substrate preparation practice for painting †' },
    primeU: { tag: 'Primer', title: 'Dabbing the supplied primer', short: 'A thin coat of the dedicated primer on each repair with the small brush supplied (20 ml with the tube; 100 ml ×2 per box of cartridges), filled after it dries.', overview: 'The putty bonds through its supplied primer: nail heads, screw holes, cracks and chips are dabbed thinly one by one and filled after the primer dries. Little is needed — never let it pool.', points: ['Thin, spot by spot.', 'Fill after it dries.', 'No excess.'], src: 'フラットパテ product page (20 ml primer supplied)' },
    fillU: { tag: 'Filling', title: 'Filling the putty: nail heads and cracks', short: 'Tube or gun pressed into each nail head and screw hole, slightly proud of the board; cracks filled along their length; chips built up to shape.', overview: 'Nail heads and screw holes: nozzle on the dimple, putty squeezed in until slightly proud of the board; cracks: squeezed in continuously along their length; chips: built up, then shaped. One-component and low-shrinkage: no need to fill in several layers.', points: ['Squeezed in spot by spot, slightly proud.', 'Cracks continuously along their length.', 'Chips built up to shape.'], src: 'フラットパテ product page (features)' },
    toolU: { tag: 'Flattening', title: 'Spatula: flush with the board', short: 'The spatula flattens the putty flush with the board and takes off the excess; almost no shrinkage after cure, the repair stays flat.', overview: 'Flatten right after filling: a nail head is smoothed to a flat face level with the board, a crack is scraped flat along its length; with almost no shrinkage there is no second fill. Wipe putty off the board before it cures.', points: ['Flush with the board.', 'Excess scraped and wiped off.', 'No shrinkage after cure.'], src: 'フラットパテ product page (features)' },
    paintU: { tag: 'Painting', title: 'Painting the whole face after cure', short: 'After the putty cures the whole face is painted: the special urethane polymer suits most finishes and bonds very well; no plasticiser, so no discolouration or dust pick-up.', overview: 'The renovation coat goes on after the putty has fully cured: the finish is applied straight over the putty with excellent adhesion; with no plasticiser the coating does not discolour or go tacky and dusty with time. Cure time not published (TBC): confirm against the painting specification.', points: ['Whole face painted after cure.', 'Excellent adhesion of the finish.', 'No staining of the finish.'], src: 'フラットパテ product page (adhesion of finishes)' },
    inspU: { tag: 'Inspection', title: 'Checking the repairs', short: 'After painting the repairs are flat and invisible, with no shrinkage dimple and no crack; no nail head missed.', overview: 'After painting a repair should be flat without a mark: check for shrinkage dimples, cracking and missed nail heads; fill and touch up anything missed.', points: ['Flat, no mark.', 'No dimple, no crack.', 'Nothing missed.'], src: 'General practice †' }
  };
  /* ================================================================ 日本語 ================================================================ */
  S.ja.civil = { name: 'RC構造物の伸縮目地・ひび割れUカット補修（土木用）', problem: '橋梁・橋脚、壁高欄、擁壁、ボックスカルバート、U字溝などRC構造物の目地は紫外線・雨・温度差に何十年も曝される：一般のシーリング材は硬化・ひび割れして雨水が入り、鉄筋腐食と凍害がそこから広がる。伸縮目地は幅広で動きも大きく、建築用では追従しきれない。収縮ひび割れを放置すれば漏水と剥落の起点になる。', solution: '{TF2000}：NETIS登録（KT-190076-VE）、農業水利施設保全補修ガイドブック掲載の1成分形ポリウレタン——超高耐候・高耐久、幅広目地に施工可。「暴露に強い」ことが最大の特長で、ノンブリードのため塗装下地にもなる。伸縮目地はバックアップ材で深さを調整して充填、収縮ひび割れはUカット→清掃→専用プライマー {OP2019}（別売）→充填・仕上げ。6Lペールはペール缶詰替え容器でカートリッジに詰め替えて施工できる。' };
  S.ja.ind = { name: '鋼板の重ね継ぎ目・ケーブルモール（工業用）', problem: '機械ハウジング、鋼製ボックス、折板・鋼板壁の重ね継ぎ目は振動と温度差で緩み、雨水と粉塵が隙間から侵入する。ケーブルモールや配電ボックスなどプラスチック部品と金属面の取り合いは水密・気密の弱点。産業現場はタクトが命：硬化の遅いシーリング材は組立と出荷を遅らせる。', solution: '{R101}：当社のポリウレタン技術で産業用に開発した速乾タイプのスタンダード——硬化が速く、硬化後は高伸度のゴム弾性体として接合部の振動・衝撃を吸収し、温度差による伸縮にも追従する。各種金属からプラスチック、ガラスまで対応。重ね継ぎ目は上板の端に沿ってフィレット状に、モールとボックスは周囲をフィレットでシール。白・Tグレー・黒の3色で塗装面に合わせる。' };
  S.ja.putty = { name: 'サイディングの釘頭・ひび割れのパテ処理（建築用パテ材）', problem: '窯業系サイディングの塗り替え前、釘頭・ビス穴のくぼみ、欠け、ひび割れをそのまま塗装しても仕上げ塗料では隠れず、後に吸水・剥離の原因になる。一般のパテは硬化後に肉やせし、可塑剤入りのパテは仕上げ塗膜を汚染してベタつき・粉塵付着を起こす。', solution: '{FLATP}（170gチューブ、20ml専用プライマー付属）／{AD3500}（320mlカートリッジ、箱に100mlプライマー×2付属）：1成分形の可撓性ウレタンパテ——硬化後の肉やせがほとんどなく補填部がフラットに仕上がる。可塑剤を含まず仕上げ塗料を汚染しない。ほとんどの仕上げ塗料と相性がよく付着性良好。清掃→付属プライマー→補填→ヘラ仕上げ→硬化後に全面塗装。' };
  X.ja.layers = { sealTF: ['シーリング材（土木用・暴露型）', 'バックアップ材面にノズルを当てゆっくり連続充填、ヘラで押さえ・仕上げ。暴露使用、塗装も可（適応しない塗料あり）', '幅20×深さ15mm（本例）；Uカット約10×10mm', '320 ml ÷（幅×深さ）÷ 1.2 m／本†；6Lペールはカートリッジに詰め替え', '指触乾燥・完全硬化：メーカー未公表（TBC）；通水・塗装は完全硬化後', '1成分形ポリウレタン；グレー／ライトグレー；NETIS KT-190076-VE'], sealR: ['シーリング材（産業用・速乾）', '重ね継ぎ目の縁とモール周囲にフィレット状に打ち、ヘラで一定の三角断面に', 'フィレット約10×8mm（本例）', '320 ml ÷（幅×深さ÷2）÷ 1.2 m／本†（三角断面）', '速乾タイプ：硬化時間未公表（TBC）；表面硬化前にテープ剥がし', 'ポリウレタン系；白／Tグレー／黒；JSIA F☆☆☆☆'], putty: ['可撓性ウレタンパテ', '釘頭・ビス穴を一点ずつ補填、ひび割れは線状に補填；ヘラで板面と面一に', '釘頭：くぼみを充填；ひび割れ：U溝10×8mm（本例）', '170gチューブ／320mlカートリッジ；使用量はくぼみの大きさによる（未公表）', '硬化後の肉やせ極小；硬化時間未公表（TBC）；硬化後に塗装', '1成分形ウレタンパテ；可塑剤なし；F☆☆☆☆・4VOC'], primP: ['パテ専用プライマー（付属）', '補填箇所に付属の小刷毛で塗布、乾燥後に補填', '薄塗り', '20ml（チューブ付属）／100ml×2（カートリッジ1箱に付属）', '乾燥後に補填（時間未公表 TBC）', '専用プライマー'] };
  X.ja.stages = { ucut: 'Uカット' };
  X.ja.co = {
    civil: [['伸縮目地とU溝', '伸縮目地は幅20mm・深さ15mm（本例）：バックアップ材で二面接着と厚みを確保。収縮ひび割れはディスクカッターでひび割れに沿って約10×10mmのU溝を切る——脆弱なひび割れ縁を取り去り、シーリング材に接着できる新鮮で厚みのある断面を与える。'], ['プライマーは別売', 'TF2000の6Lペールにも320mlカートリッジにもプライマーは付属しない：専用高性能プライマーOP-2019（100ml／500ml缶）を別途手配し、塗布後15分以上乾燥させてから充填する。'], ['暴露使用、塗装不要', '土木構造物の目地は多くが暴露のまま：TF2000の超高耐候性はそのためのもの。塗装する場合（壁高欄の塗装など）はノンブリードだが適応しない塗料があるので、事前にメーカーへ確認。']],
    ind: [['重ね継ぎ目：目地ではなくフィレット', '重ね継ぎ目には「目地」がない：シーリング材は上板の端に沿ってフィレット状に打ち、板端を覆って下板に接着させる——バックアップ材は不要、テープは下板側のみ。ヘラでフィレットを一定の断面に押さえる。'], ['プラスチック対金属', 'ケーブルモール（PVC）と配電ボックスを鋼板に固定：周囲をフィレットでシール。101Rは各種金属からプラスチック、ガラスまで対応。表面は溶剤拭きで脱脂してからテープを貼る。'], ['速乾、タクトを止めない', '101Rは速乾タイプ：硬化が速くラインを待たせない。硬化後は高伸度のゴム弾性体として振動・衝撃を吸収。プライマー付属なし——特殊な被着体は事前に接着試験を。']],
    putty: [['釘頭と欠け', '塗り替え前に、サイディングの釘頭・ビス穴、欠け、ひび割れを先に補填：パテは硬化後ほとんど肉やせせず、補填部はフラットで仕上げ塗料に跡が残らない。'], ['付属プライマー、そして補填', 'チューブには20mlの専用プライマーと小刷毛、カートリッジは1箱に100ml×2が付属：補填箇所に先にプライマーを塗り、乾燥後にチューブまたはガンで補填し、ヘラで板面と面一に。'], ['仕上げ塗料を汚さない', '可塑剤を含まない：パテから油分が滲み出て仕上げ塗料を変色・ベタつかせることがない。特殊ウレタンポリマーがほとんどの仕上げ塗料と相性よく、硬化後に全面塗装。']]
  };
