    SLT[l]['sl.dl.tfcat'] = { zh: 'TF2000 型錄（PDF，製造商 2025/07）', en: 'TF2000 catalogue (PDF, manufacturer 2025/07)', ja: '超耐シーラーTF2000カタログ（PDF、2025/07）' }[l];
